import {
  ALLOWED_SERVICE_DOMAINS,
  FAN_ONLY_HVAC_MODE,
  FORBIDDEN_SERVICES,
} from "./constants";
import { getResolvedPowerOnMode } from "./state";
import type { HomeAssistant, ResolvedCardConfig, TargetAdjustment } from "./types";

export interface ServiceCall {
  domain: string;
  service: string;
  data: Record<string, unknown>;
}

export function assertAllowedService(domain: string, service: string): void {
  const full = `${domain}.${service}`;
  if ((FORBIDDEN_SERVICES as readonly string[]).includes(full)) {
    throw new Error(`Forbidden service call: ${full}`);
  }
  if (!(ALLOWED_SERVICE_DOMAINS as readonly string[]).includes(domain)) {
    throw new Error(`Service domain not allowed: ${domain}`);
  }
}

export function buildPowerOnCall(config: ResolvedCardConfig): ServiceCall {
  return {
    domain: "climate",
    service: "set_hvac_mode",
    data: {
      entity_id: config.climate_entity,
      hvac_mode: getResolvedPowerOnMode(config),
    },
  };
}

export function buildFanOnlyCall(config: ResolvedCardConfig): ServiceCall {
  return {
    domain: "climate",
    service: "set_hvac_mode",
    data: {
      entity_id: config.climate_entity,
      hvac_mode: FAN_ONLY_HVAC_MODE,
    },
  };
}

export function buildPowerOffCall(config: ResolvedCardConfig): ServiceCall {
  return {
    domain: "climate",
    service: "set_hvac_mode",
    data: {
      entity_id: config.climate_entity,
      hvac_mode: "off",
    },
  };
}

export function buildSetTemperatureCall(
  config: ResolvedCardConfig,
  targets: TargetAdjustment,
): ServiceCall {
  return {
    domain: "climate",
    service: "set_temperature",
    data: {
      entity_id: config.climate_entity,
      target_temp_low: targets.targetLow,
      target_temp_high: targets.targetHigh,
      hvac_mode: "heat_cool",
    },
  };
}

export function buildFanAutoOnCall(config: ResolvedCardConfig): ServiceCall {
  return {
    domain: "input_boolean",
    service: "turn_on",
    data: {
      entity_id: config.fan_auto_entity,
    },
  };
}

export function buildFanAutoOffCall(config: ResolvedCardConfig): ServiceCall {
  return {
    domain: "input_boolean",
    service: "turn_off",
    data: {
      entity_id: config.fan_auto_entity,
    },
  };
}

export function buildFanOverrideCall(
  config: ResolvedCardConfig,
  option: string,
): ServiceCall {
  return {
    domain: "input_select",
    service: "select_option",
    data: {
      entity_id: config.fan_override_entity,
      option,
    },
  };
}

export function buildBoostCall(config: ResolvedCardConfig): ServiceCall {
  return {
    domain: "script",
    service: "turn_on",
    data: {
      entity_id: config.boost_script_entity,
    },
  };
}

export function buildBoostCancelCall(config: ResolvedCardConfig): ServiceCall {
  return {
    domain: "script",
    service: "turn_on",
    data: {
      entity_id: config.boost_cancel_script_entity,
    },
  };
}

function entityDomain(entityId: string): string {
  const separator = entityId.indexOf(".");
  return separator === -1 ? entityId : entityId.slice(0, separator);
}

export function buildDryOffCall(config: ResolvedCardConfig): ServiceCall | null {
  if (!config.dry_entity) return null;
  return {
    domain: entityDomain(config.dry_entity),
    service: "turn_off",
    data: {
      entity_id: config.dry_entity,
    },
  };
}

export async function callService(
  hass: HomeAssistant,
  call: ServiceCall,
): Promise<void> {
  assertAllowedService(call.domain, call.service);
  await hass.callService(call.domain, call.service, call.data);
}

export async function setFanOnlyMode(
  hass: HomeAssistant,
  config: ResolvedCardConfig,
  enabled: boolean,
): Promise<void> {
  await callService(
    hass,
    enabled ? buildFanOnlyCall(config) : buildPowerOnCall(config),
  );
}

export async function setPower(
  hass: HomeAssistant,
  config: ResolvedCardConfig,
  on: boolean,
): Promise<void> {
  if (!on) {
    await cancelDry(hass, config);
    await callService(hass, buildPowerOffCall(config));
    return;
  }
  await callService(hass, buildPowerOnCall(config));
}

export async function setTemperature(
  hass: HomeAssistant,
  config: ResolvedCardConfig,
  targets: TargetAdjustment,
): Promise<void> {
  await callService(hass, buildSetTemperatureCall(config, targets));
}

export async function setFanAuto(
  hass: HomeAssistant,
  config: ResolvedCardConfig,
  enabled: boolean,
): Promise<void> {
  if (config.fan_auto_entity) {
    await callService(
      hass,
      enabled ? buildFanAutoOnCall(config) : buildFanAutoOffCall(config),
    );
    return;
  }

  if (config.fan_override_entity) {
    await callService(hass, buildFanOverrideCall(config, enabled ? "auto" : "low"));
  }
}

export async function setFanOverride(
  hass: HomeAssistant,
  config: ResolvedCardConfig,
  option: string,
): Promise<void> {
  await callService(hass, buildFanOverrideCall(config, option));
}

export async function triggerBoost(
  hass: HomeAssistant,
  config: ResolvedCardConfig,
): Promise<void> {
  await callService(hass, buildBoostCall(config));
}

export async function cancelBoost(
  hass: HomeAssistant,
  config: ResolvedCardConfig,
): Promise<void> {
  if (!config.boost_cancel_script_entity) return;
  await callService(hass, buildBoostCancelCall(config));
}

export async function cancelDry(
  hass: HomeAssistant,
  config: ResolvedCardConfig,
): Promise<void> {
  const call = buildDryOffCall(config);
  if (!call) return;
  await callService(hass, call);
}
